package com.brasa.restaurant.model;import com.brasa.restaurant.enums.Enums.*;import jakarta.persistence.*;@Entity@Table(name="funcionarios")public class Funcionario extends BaseEntity{@Column(name="restaurante_id",nullable=false)private String restauranteId;private String nome;@Enumerated(EnumType.STRING)private Cargo cargo;@Enumerated(EnumType.STRING)private Turno turno;private boolean ativo=true;public String getRestauranteId(){return restauranteId;}public void setRestauranteId(String v){restauranteId=v;}public String getNome(){return nome;}public void setNome(String v){nome=v;}public Cargo getCargo(){return cargo;}public void setCargo(Cargo v){cargo=v;}public Turno getTurno(){return turno;}public void setTurno(Turno v){turno=v;}public boolean isAtivo(){return ativo;}public void setAtivo(boolean v){ativo=v;}}
